// data.ingest_plan — build+execute orchestration (conv-26) against the
// frozen Python oracle (fixtures/ingest_plan/main, generated by
// tools/oracle/generate_ingest_plan_fixtures.py driving the real
// DataCatalogService + resources/ingest_plan.py with the geoviz engines
// blocked — the engine-missing fallback this side implements).
//
// The replay copies the PRE-execute tree, relocates the seeded RAW
// identity to its own root (same harness step the generator runs), then
// must reproduce: the pure plan (items/identities/roles/duplicates/
// primaries), the confirmed execute report, the post-execute SQL page,
// the project entity/binding tree, the payload layout, and the idempotent
// re-run — all after applying the SAME masker the generator froze with
// (ids → kind#first-seen, ISO timestamps → <TS>, scratch root → <ROOT>).
#include "pwb_test.hpp"
#include "compare_json.hpp"

#include "pwb/catalog/paged_sql.hpp"
#include "pwb/catalog/repository.hpp"
#include "pwb/catalog/sqlite.hpp"
#include "pwb/data/ingest_exec.hpp"
#include "pwb/data/ingest_plan.hpp"
#include "pwb/domain/json.hpp"
#include "pwb/project/paths.hpp"

#include <algorithm>
#include <filesystem>
#include <fstream>
#include <map>
#include <regex>
#include <sstream>
#include <string>
#include <vector>

namespace {

namespace fs = std::filesystem;
using pwb::domain::Json;

fs::path fixture_dir() {
    return fs::path(PWB_DATA_FIXTURE_DIR) / "ingest_plan" / "main";
}

Json load_json(const fs::path& file) {
    std::ifstream stream(file, std::ios::binary);
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return Json::parse(buffer.str(), nullptr, false);
}

// ---- masker (generator parity) --------------------------------------------

const std::regex& id_regex() {
    static const std::regex pattern(
        "(asset|ver|run|well|ent|svy|link|wa)_[0-9a-f]{12}");
    return pattern;
}

const std::regex& ts_regex() {
    static const std::regex pattern(
        "[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}"
        "(\\.[0-9]+)?(([+-][0-9]{2}:[0-9]{2})|Z)?");
    return pattern;
}

struct MaskCounters {
    std::map<std::string, std::map<std::string, std::string>> by_kind;
};

std::string replace_all(std::string text, const std::string& needle,
                        const std::string& replacement) {
    if (needle.empty()) return text;
    std::size_t at = text.find(needle);
    while (at != std::string::npos) {
        text.replace(at, needle.size(), replacement);
        at = text.find(needle, at + replacement.size());
    }
    return text;
}

std::string mask_string(const std::string& value, const std::string& root,
                        MaskCounters& counters) {
    std::string masked = replace_all(value, root, "<ROOT>");
    std::string out;
    auto id_begin = std::sregex_iterator(masked.begin(), masked.end(),
                                         id_regex());
    auto id_end = std::sregex_iterator();
    std::size_t last = 0;
    for (auto it = id_begin; it != id_end; ++it) {
        const std::smatch match = *it;
        out += masked.substr(last, match.position() - last);
        const std::string kind = match[1].str();
        const std::string full = match[0].str();
        std::string& slot = counters.by_kind[kind][full];
        if (slot.empty()) {
            slot = kind + "#" +
                   std::to_string(counters.by_kind[kind].size() - 1);
        }
        out += slot;
        last = match.position() + match.length();
    }
    out += masked.substr(last);
    return std::regex_replace(out, ts_regex(), "<TS>");
}

Json mask_json(const Json& value, const std::string& root,
               MaskCounters& counters) {
    if (value.is_string()) {
        return Json(mask_string(value.get<std::string>(), root, counters));
    }
    if (value.is_array()) {
        Json out = Json::array();
        for (const auto& entry : value) out.push_back(mask_json(entry, root, counters));
        return out;
    }
    if (value.is_object()) {
        Json out = Json::object();
        for (auto it = value.begin(); it != value.end(); ++it) {
            const std::string key =
                mask_string(it.key(), root, counters);
            out[key] = mask_json(it.value(), root, counters);
        }
        return out;
    }
    return value;
}

// ---- scratch fixture -------------------------------------------------------

struct Scratch {
    fs::path root;

    Scratch() {
        root = fs::temp_directory_path() / "pwb_ingest_plan_replay";
        std::error_code ec;
        fs::remove_all(root, ec);
        fs::create_directories(root, ec);
        fs::copy(fixture_dir() / "tree", root,
                 fs::copy_options::recursive
                     | fs::copy_options::overwrite_existing,
                 ec);
        relocate_seed_identity();
    }

    ~Scratch() {
        std::error_code ec;
        fs::remove_all(root, ec);
    }

    // Same harness step the generator runs: the fixture stores the seeded
    // managed-RAW identity as a FIXED RELATIVE marker (checkout-path-
    // independent); rewrite it to this replay's incoming root so duplicate
    // matching is location-independent.
    void relocate_seed_identity() {
        auto opened = pwb::catalog::Database::open(
            root / "demo.artifacts" / "metadata" / "catalog.sqlite",
            pwb::catalog::SqliteOpenMode::ReadWrite);
        PWB_CHECK(opened.is_ok());
        pwb::catalog::Database& db = opened.value();
        pwb::catalog::Statement update = db.prepare(
            "UPDATE versions SET source_uri = replace(source_uri, ?, ?)");
        PWB_CHECK(update.is_valid());
        update.bind(1, "__PWB_INGEST_ROOT__");
        update.bind(2, (root / "incoming").generic_string());
        update.step_done();
    }
};

std::vector<std::string> payload_tree_files(const fs::path& root) {
    std::vector<std::string> files;
    const fs::path bookkeeping[] = {root / "demo.artifacts" / "metadata",
                                    root / "incoming"};
    for (const auto& entry : fs::recursive_directory_iterator(root)) {
        std::error_code ec;
        if (!entry.is_regular_file(ec) || ec) continue;
        bool excluded = false;
        for (const fs::path& base : bookkeeping) {
            std::error_code rel_ec;
            const fs::path rel = fs::relative(entry.path(), base, rel_ec);
            if (!rel_ec && rel != "" &&
                (rel.begin() == rel.end() || (*rel.begin()) != "..")) {
                excluded = true;
                break;
            }
        }
        if (excluded) continue;
        files.push_back(fs::relative(entry.path(), root).generic_string());
    }
    std::vector<std::string> masked;
    for (const std::string& file : files) {
        masked.push_back(std::regex_replace(file, id_regex(), "<ID>"));
    }
    std::sort(masked.begin(), masked.end());
    return masked;
}

// Canonical page: name order stands; equal-name rows tie-break on content
// (the SQL id tail is random per run) — same rule the generator froze with.
Json canonical_page(const Json& page) {
    Json rows = page;
    if (rows.is_array()) {
        std::sort(rows.begin(), rows.end(),
                  [](const Json& a, const Json& b) {
                      const std::string ka =
                          a.value("name", std::string()) + "|" + a.dump();
                      const std::string kb =
                          b.value("name", std::string()) + "|" + b.dump();
                      return ka < kb;
                  });
    }
    return rows;
}

// metadata is a JSON TEXT column — Python freezes json.dumps spacing, this
// side dumps compact; compare parsed (conv-15 decisions D7).
Json parse_metadata_fields(Json value) {
    if (value.is_array()) {
        Json out = Json::array();
        for (const Json& entry : value) {
            out.push_back(parse_metadata_fields(entry));
        }
        return out;
    }
    if (value.is_object() && value.contains("metadata") &&
        value["metadata"].is_string()) {
        Json parsed = Json::parse(value["metadata"].get<std::string>(),
                                  nullptr, false);
        if (!parsed.is_discarded()) value["metadata"] = parsed;
    }
    return value;
}

}  // namespace

PWB_TEST(plan_matches_the_frozen_python_oracle) {
    Scratch scratch;
    const Json oracle = load_json(fixture_dir() / "oracle.json");

    pwb::project::ProjectManager manager(scratch.root / "demo.paleo.json");
    auto loaded = manager.load();
    PWB_CHECK(loaded.is_ok());

    pwb::catalog::CatalogRepository repository(
        pwb::project::catalog_sqlite_for(scratch.root / "demo.paleo.json"));
    auto catalog_doc = repository.open_read_only();
    PWB_CHECK(catalog_doc.is_ok());

    const pwb::data::IngestPlan plan = pwb::data::build_ingest_plan(
        scratch.root / "incoming", loaded.value().document,
        {.preferred_only = true, .catalog = &catalog_doc.value()});

    MaskCounters counters;
    const Json masked_plan = mask_json(plan.to_json(), scratch.root.string(),
                                       counters);
    const Json masked_summary = mask_json(plan.summary(), scratch.root.string(),
                                          counters);
    if (auto diff = pwb_test::json_compare(oracle["plan"], masked_plan)) {
        std::cout << "  FAIL plan: " << *diff << "\n";
        PWB_CHECK(false);
    }
    if (auto diff =
            pwb_test::json_compare(oracle["summary"], masked_summary)) {
        std::cout << "  FAIL summary: " << *diff << "\n";
        PWB_CHECK(false);
    }
    PWB_CHECK(plan.items.size() == 9);
    PWB_CHECK(plan.duplicates().size() == 1);
}

PWB_TEST(execute_replays_import_bind_and_page) {
    Scratch scratch;
    const Json oracle = load_json(fixture_dir() / "oracle.json");

    auto session_result = pwb::data::WritableSession::open(
        scratch.root / "demo.paleo.json");
    PWB_CHECK(session_result.is_ok());
    pwb::data::WritableSession& session = session_result.value();

    auto catalog_doc = session.repository().open_read_only();
    PWB_CHECK(catalog_doc.is_ok());
    pwb::data::IngestPlan plan = pwb::data::build_ingest_plan(
        scratch.root / "incoming", session.document(),
        {.preferred_only = true, .catalog = &catalog_doc.value()});
    for (auto& item : plan.items) {
        if (item.decision == "pending") item.decision = "accept";
    }

    const pwb::data::IngestExecuteReport report =
        pwb::data::execute_ingest_plan(plan, session);

    // The generator froze plan → report → page with ONE shared counter
    // table (the seeded duplicate asset claims asset#0 in the plan's
    // duplicate_of fields); warm the counters the same way before masking.
    MaskCounters counters;
    mask_json(plan.to_json(), scratch.root.string(), counters);
    if (auto diff = pwb_test::json_compare(
            oracle["execute_report"],
            mask_json(report.to_json(), scratch.root.string(), counters))) {
        std::cout << "  FAIL execute report: " << *diff << "\n";
        PWB_CHECK(false);
    }

    // Post-execute store: SQL page straight from catalog.sqlite.
    auto opened = pwb::catalog::Database::open(
        pwb::project::catalog_sqlite_for(scratch.root / "demo.paleo.json"),
        pwb::catalog::SqliteOpenMode::ReadOnly);
    PWB_CHECK(opened.is_ok());
    pwb::catalog::EntityPageQuery query;
    query.limit = 100;
    const std::vector<Json> rows =
        pwb::catalog::search_assets_page_sql(opened.value(), query);
    Json page = Json::array();
    for (const Json& row : rows) page.push_back(row);
    Json masked_page = canonical_page(
        mask_json(page, scratch.root.string(), counters));
    masked_page = parse_metadata_fields(std::move(masked_page));
    Json oracle_page = parse_metadata_fields(oracle["asset_page_after"]);
    if (auto diff = pwb_test::json_compare(oracle_page, masked_page)) {
        std::cout << "  FAIL asset page: " << *diff << "\n";
        PWB_CHECK(false);
    }

    // Project document: entity trees + links.
    const Json& root = session.document().root();
    const Json empty = Json::array();
    const Json* sections[] = {
        root.contains("entity_asset_links") ? &root["entity_asset_links"] : &empty,
        root.contains("wells") ? &root["wells"] : &empty,
        root.contains("seismic_surveys") ? &root["seismic_surveys"] : &empty,
        root.contains("geological_entities") ? &root["geological_entities"] : &empty,
    };
    const char* oracle_keys[] = {"links_after", "wells_after", "surveys_after",
                                 "geological_after"};
    for (std::size_t i = 0; i < 4; ++i) {
        const Json masked =
            mask_json(*sections[i], scratch.root.string(), counters);
        if (auto diff =
                pwb_test::json_compare(oracle[oracle_keys[i]], masked)) {
            std::cout << "  FAIL " << oracle_keys[i] << ": " << *diff << "\n";
            if (std::string(oracle_keys[i]) == "links_after") {
                for (std::size_t j = 0;
                     j < masked.size() && j < oracle[oracle_keys[i]].size();
                     ++j) {
                    std::cout << "    [" << j << "] oracle="
                              << oracle[oracle_keys[i]][j]["asset_id"]
                              << " actual=" << masked[j]["asset_id"]
                              << " role=" << masked[j]["role"] << "\n";
                }
            }
            PWB_CHECK(false);
        }
    }

    // Persist the mutated project like the generator did before freezing
    // the tree (its save rotates demo.paleo.json.bak — part of the frozen
    // file list).
    auto saved = session.manager().save(session.document());
    PWB_CHECK(saved.is_ok());

    // Payload layout on disk.
    Json tree_files = Json::array();
    for (const std::string& file : payload_tree_files(scratch.root)) {
        tree_files.push_back(file);
    }
    if (auto diff = pwb_test::json_compare(oracle["tree_files_after"],
                                           tree_files)) {
        std::cout << "  FAIL tree files: " << *diff << "\n";
        for (const auto& entry : tree_files) {
            if (!std::any_of(oracle["tree_files_after"].begin(),
                             oracle["tree_files_after"].end(),
                             [&](const Json& want) {
                                 return want == entry;
                             })) {
                std::cout << "    extra: " << entry << "\n";
            }
        }
        for (const auto& want : oracle["tree_files_after"]) {
            if (!std::any_of(tree_files.begin(), tree_files.end(),
                             [&](const Json& entry) { return want == entry; })) {
                std::cout << "    missing: " << want << "\n";
            }
        }
        PWB_CHECK(false);
    }
}

PWB_TEST(rerun_is_idempotent_and_save_reopens) {
    Scratch scratch;
    const Json oracle = load_json(fixture_dir() / "oracle.json");

    {
        auto session_result = pwb::data::WritableSession::open(
            scratch.root / "demo.paleo.json");
        PWB_CHECK(session_result.is_ok());
        pwb::data::WritableSession& session = session_result.value();
        auto catalog_doc = session.repository().open_read_only();
        PWB_CHECK(catalog_doc.is_ok());
        pwb::data::IngestPlan plan = pwb::data::build_ingest_plan(
            scratch.root / "incoming", session.document(),
            {.preferred_only = true, .catalog = &catalog_doc.value()});
        for (auto& item : plan.items) {
            if (item.decision == "pending") item.decision = "accept";
        }
        const auto first = pwb::data::execute_ingest_plan(plan, session);
        PWB_CHECK(first.imported_version_ids.size() == 8);
        PWB_CHECK(first.cancelled == false);
        // Persist the mutated project (entities + links) like the caller.
        auto saved = session.manager().save(session.document());
        PWB_CHECK(saved.is_ok());
    }

    // Reopen: the saved document + committed catalog survive a reload, and
    // a re-executed plan imports nothing new (recovery contract).
    auto session2 = pwb::data::WritableSession::open(
        scratch.root / "demo.paleo.json");
    PWB_CHECK(session2.is_ok());
    auto catalog_doc2 = session2.value().repository().open_read_only();
    PWB_CHECK(catalog_doc2.is_ok());
    PWB_CHECK(catalog_doc2.value().assets.size() == 9);

    pwb::data::IngestPlan plan2 = pwb::data::build_ingest_plan(
        scratch.root / "incoming", session2.value().document(),
        {.preferred_only = true, .catalog = &catalog_doc2.value()});
    for (auto& item : plan2.items) {
        if (item.decision == "pending") item.decision = "accept";
    }
    const auto rerun = pwb::data::execute_ingest_plan(plan2, session2.value());

    MaskCounters counters;
    const Json masked = mask_json(rerun.to_json(), scratch.root.string(),
                                  counters);
    // Compare against the generator's rerun projection (subset of to_json).
    Json projected = Json::object();
    projected["imported_version_ids"] = masked["imported_version_ids"];
    projected["skipped"] = masked["skipped"];
    projected["issues"] = masked["issues"];
    projected["cancelled"] = masked["cancelled"];
    if (auto diff =
            pwb_test::json_compare(oracle["rerun_report"], projected)) {
        std::cout << "  FAIL rerun: " << *diff << "\n";
        PWB_CHECK(false);
    }
    PWB_CHECK(rerun.imported_version_ids.empty());
    PWB_CHECK(rerun.skipped.size() == 9);
}

PWB_TEST(cancel_stops_between_chunks_and_rerun_completes) {
    // Behavioral check (no oracle — deterministic by construction): cancel
    // after the first chunk leaves a consistent partial import; executing
    // again finishes the job without duplicating anything.
    Scratch scratch;
    auto session_result = pwb::data::WritableSession::open(
        scratch.root / "demo.paleo.json");
    PWB_CHECK(session_result.is_ok());
    pwb::data::WritableSession& session = session_result.value();
    auto catalog_doc = session.repository().open_read_only();
    PWB_CHECK(catalog_doc.is_ok());
    pwb::data::IngestPlan plan = pwb::data::build_ingest_plan(
        scratch.root / "incoming", session.document(),
        {.preferred_only = true, .catalog = &catalog_doc.value()});
    for (auto& item : plan.items) {
        if (item.decision == "pending") item.decision = "accept";
    }

    int chunks_seen = 0;
    const auto partial = pwb::data::execute_ingest_plan(
        plan, session, {.chunk_size = 2,
                        .cancel = [&chunks_seen]() {
                            return ++chunks_seen > 1;
                        }});
    PWB_CHECK(partial.cancelled);
    PWB_CHECK(partial.imported_version_ids.size() == 2);
    PWB_CHECK(partial.issues.empty());

    const auto finished = pwb::data::execute_ingest_plan(plan, session);
    PWB_CHECK(!finished.cancelled);
    PWB_CHECK(finished.imported_version_ids.size() == 6);
    // 2 idempotency skips (chunk 1 already committed) + 1 duplicate skip.
    PWB_CHECK(finished.skipped.size() == 3);
    PWB_CHECK(finished.issues.empty());

    auto reopened = session.repository().open_read_only();
    PWB_CHECK(reopened.is_ok());
    PWB_CHECK(reopened.value().assets.size() == 9);
}
